  sage:'EEF2EC',g700:'235F40',g800:'222222',g600:'666666',g400:'AAAAAA',g300:'D0D0D0',g200:'DFDFDF',g100:'EFEFEF',hair:'E7E7E2'};
var A='assets/';
var WMB=A+'magoya-wordmark-black.svg', WMC=A+'magoya-wordmark-cream.svg';
var AG=A+'studio/icons/agro/', AI=A+'studio/icons/ai/', CL=A+'logos/clients/', PT=A+'logos/partners/', PH=A+'photos/';

function R(o){o.k='r';return o;}
function T(text,o){o=o||{};o.k='t';o.text=text;return o;}
function IMG(o){o.k='i';return o;}
function CH(o){o.k='c';return o;}
function bg(fill){return R({x:0,y:0,w:100,h:56.25,fill:fill});}
/* barra superior de slide de contenido + número */
function chrome(pg,dark,x){
  x=(x===undefined)?7.5:x;
  return [IMG({src:dark?WMC:WMB,x:x,y:3.2,w:11,h:3.007}),
          T(pg,{x:76.5,y:3.5,w:16,h:2.2,s:1.15,b:true,c:dark?C.cr300:C.g400,al:'right',cs:1.1})];
}
/* label + valor de stat */
function stat(x,y,val,desc,size,c,dc,wd){
  return [T(val,{x:x,y:y,w:wd||24,h:size*0.9,s:size,b:true,c:c||C.ink,tight:true,lh:.95}),
          T(desc,{x:x,y:y+size*0.92,w:wd||24,h:6,s:1.4,c:dc||C.g600,lh:1.25})];
}
function rule(x,y,w){return R({x:x,y:y,w:w||14,h:.8,fill:C.lime,radius:.4});}
function chip(x,y,text,col,w){
