          T(text,{x:x,y:y,w:w,h:3.1,s:1.25,b:true,c:col,al:'center',va:'middle'})];
}

/* ---------- 5. carga y rasterizado de assets ---------- */
var cache={};
function fetchText(u){return fetch(u).then(function(r){if(!r.ok)throw new Error(u);return r.text();});}
function blobToDataURL(b){return new Promise(function(res,rej){var f=new FileReader();
  f.onload=function(){res(f.result);};f.onerror=rej;f.readAsDataURL(b);});}
function rasterize(url,w,h,gray,mime){
  return new Promise(function(res,rej){
    var im=new Image();
    im.onload=function(){
      var cv=document.createElement('canvas');cv.width=w;cv.height=h;
      var cx=cv.getContext('2d');
      if(mime==='image/jpeg'){cx.fillStyle='#FFFFFF';cx.fillRect(0,0,w,h);}
      cx.drawImage(im,0,0,w,h);
      if(gray){try{var d=cx.getImageData(0,0,w,h),p=d.data;
        for(var i=0;i<p.length;i+=4){var l=0.299*p[i]+0.587*p[i+1]+0.114*p[i+2];p[i]=p[i+1]=p[i+2]=l;}
        cx.putImageData(d,0,0);}catch(e){}}
      res(mime==='image/jpeg'?cv.toDataURL('image/jpeg',0.86):cv.toDataURL('image/png'));
    };
    im.onerror=function(){rej(new Error('img '+url));};
    im.src=url;
  });
}
/* ancho de rasterizado según el tamaño real en el slide (200 ppi) */
function pxFor(cqw){return Math.max(140,Math.min(1500,Math.round((cqw||10)*U*200)));}
/* svg → png (permite teñir currentColor / swap de hex) */
function svgPng(src,opt){
  opt=opt||{};
  var px=pxFor(opt.w);
  return fetchText(src).then(function(t){
    if(opt.tint)t=t.replace(/currentColor/g,opt.tint);
    if(opt.swap)opt.swap.forEach(function(p){t=t.split(p[0]).join(p[1]);});
    var vb=/viewBox="([\d.\-\s]+)"/.exec(t), ar=1;
    if(vb){var n=vb[1].trim().split(/\s+/).map(Number);if(n[2]&&n[3])ar=n[3]/n[2];}
    t=t.replace(/<svg([^>]*)>/,function(m,at){
      at=at.replace(/\s(width|height)="[^"]*"/g,'');
      return '<svg'+at+' width="'+px+'" height="'+Math.round(px*ar)+'">';
    });
    var url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(t);
    return rasterize(url,px,Math.round(px*ar),opt.gray);
  });
}
function asset(src,opt){
  opt=opt||{};
  var px=pxFor(opt.w);
  var key=src+'|'+(opt.tint||'')+'|'+(opt.gray?'g':'')+'|'+px+'|'+(opt.swap?JSON.stringify(opt.swap):'');
  if(cache[key])return cache[key];
  var p;
  if(/\.svg$/i.test(src)) p=svgPng(src,opt);
  else p=fetch(src).then(function(r){if(!r.ok)throw new Error(src);return r.blob();}).then(blobToDataURL)
      .then(function(d){return new Promise(function(res,rej){var im=new Image();
        im.onload=function(){
          var w=Math.min(im.naturalWidth,px*2);
          res(rasterize(d,w,Math.round(w*im.naturalHeight/im.naturalWidth),opt.gray,'image/jpeg'));};
        im.onerror=rej;im.src=d;});});
  p=p.catch(function(e){console.warn('[deck-kit] asset omitido:',src,e.message);return null;});
  cache[key]=p;return p;
}

/* ---------- 6. render de un spec a una slide del pptx ----------
   Las imágenes se precargan ANTES de pintar para que el orden del array
   sea el orden z real (scrims y paños quedan detrás del texto). */
function paint(pptx,slide,shapes){
  shapes=shapes.filter(Boolean);
  var imgs=shapes.filter(function(s){return s.k==='i';});
  return Promise.all(imgs.map(function(s){return asset(s.src,s);})).then(function(data){
    var map={};imgs.forEach(function(s,i){map[i]=data[i];s._ix=i;});
    shapes.forEach(function(s){
      if(s.k==='r'){
        slide.addShape(s.radius?pptx.ShapeType.roundRect:pptx.ShapeType.rect,{
          x:IN(s.x),y:IN(s.y),w:IN(s.w),h:IN(s.h),
          fill:s.fill?(s.alpha!==undefined?{color:s.fill,transparency:s.alpha}:{color:s.fill}):{type:'none'},
          line:s.line?{color:s.line,width:s.lw||1}:{type:'none'},
          rectRadius:s.radius?IN(s.radius):0});
      } else if(s.k==='t'){
        var size=s.s||1.75;
        slide.addText(s.text,{x:IN(s.x),y:IN(s.y),w:IN(s.w),h:IN(s.h||5),
          fontFace:'Manrope',fontSize:FS(size),bold:!!s.b,color:s.c||C.ink,
          align:s.al||'left',valign:s.va||'top',
          charSpacing:s.cs!==undefined?s.cs:(s.tight?-(FS(size)*0.03):0),
          lineSpacingMultiple:s.lh||1.2,margin:0,isTextBox:true});
      } else if(s.k==='i'){
        var d=map[s._ix];if(!d)return;
        var o={data:d,x:IN(s.x),y:IN(s.y),w:IN(s.w),h:IN(s.h)};
        if(s.fit)o.sizing={type:s.fit,w:IN(s.w),h:IN(s.h)};
        slide.addImage(o);
      } else if(s.k==='c'){
        slide.addChart(s.type,s.data,Object.assign({
          x:IN(s.x),y:IN(s.y),w:IN(s.w),h:IN(s.h),
          showLegend:false,showTitle:false,showValue:false,
          catAxisLabelFontFace:'Manrope',catAxisLabelFontSize:11,catAxisLabelColor:C.g600,
          valAxisHidden:true,catAxisLineShow:false,valGridLine:{style:'none'},
          chartArea:{fill:{type:'none'}},plotArea:{fill:{type:'none'}}},s.opts||{}));
      } else if(s.k==='tb'){
        slide.addTable(s.rows,Object.assign({
          x:IN(s.x),y:IN(s.y),w:IN(s.w),fontFace:'Manrope',fontSize:FS(1.5),
          color:C.ink,valign:'middle',autoPage:false},s.opts||{}));
      }
    });
  });
}

/* ---------- 7. helpers de composición ---------- */
function rowsBlock(x,y,w,items,hl,numC){
  var out=[],rh=6.2;
  items.forEach(function(it,i){
    var yy=y+i*rh;
    if(i===hl)out.push(R({x:x,y:yy,w:w,h:rh-.5,fill:C.lime,radius:.7}));
    else out.push(R({x:x,y:yy+rh-.55,w:w,h:.12,fill:C.hair}));
    out.push(T(it.n,{x:x+1.2,y:yy+1.4,w:6.5,h:3,s:2.2,b:true,c:(i===hl)?C.ink:(numC||C.ink)}));
    out.push(T(it.t,{x:x+8.5,y:yy+1.7,w:w-10,h:4,s:1.6,b:i===hl,lh:1.2}));
  });
  return out;
}
function timeline(x,y,w,steps,on){
  var out=[R({x:x+1,y:y+.68,w:w-3,h:.18,fill:C.g300})],sw=w/steps.length;
  steps.forEach(function(s,i){
    var sx=x+i*sw;
    out.push(R({x:sx,y:y,w:1.5,h:1.5,fill:(i===on)?C.lime:C.g900,radius:.75}));
    out.push(T(s.b,{x:sx,y:y+2.5,w:sw-2,h:2.4,s:1.5,b:true,lh:1.1}));
    out.push(T(s.s,{x:sx,y:y+4.9,w:sw-2,h:4.5,s:1.25,c:C.g600,lh:1.25}));
  });
  return out;
}
function card(x,y,w,h,fill,line){return R({x:x,y:y,w:w,h:h,fill:fill,line:line,lw:.75,radius:1.4});}
function iconDot(x,y,d,ic,lime){
  return [R({x:x,y:y,w:d,h:d,fill:lime?C.lime:C.ink,radius:d/2}),
          IMG({src:AG+ic,x:x+d*0.28,y:y+d*0.28,w:d*0.44,h:d*0.44,tint:lime?'#161616':'#F6F1EB'})];
}
function checkLine(x,y,w,t){
  return [T('→',{x:x,y:y,w:3,h:2.6,s:1.6,b:true,c:C.em7}),
          T(t,{x:x+2.6,y:y,w:w-2.6,h:4,s:1.55,lh:1.25})];
}
function logoRow(list,x,y,w,h,cols,gapx,gapy){
  var out=[],cw=(w-gapx*(cols-1))/cols;
  list.forEach(function(src,i){
    var c=i%cols,r=Math.floor(i/cols);
    out.push(IMG({src:src,x:x+c*(cw+gapx),y:y+r*(h+gapy),w:cw,h:h,fit:'contain',gray:true}));
  });
  return out;
}

